from pathlib import Path
p=Path('/home/user');s=(p/'page-shell.html').read_text()
widget='''<button class="site-map" id="siteMapToggle" aria-label="Toggle construction site overview" aria-pressed="false"><div class="map-title">SITE PLAN <span>46 × 34 M</span></div><svg viewBox="-25 -19 50 38" role="img" aria-label="Site plan with current excavator position"><rect x="-23" y="-17" width="46" height="34" rx=".5" fill="#c9c9b5" stroke="#8d9b7c" stroke-width=".35"/><path d="M-23 -3.8H23V3.8H-23Z M-3.8 -17H3.8V17H-3.8Z" fill="#b0b69d"/><path d="M-23 0H23M0 -17V17" stroke="#e6e5cc" stroke-width=".3" stroke-dasharray="1 1"/><rect x="-16" y="-12.3" width="8.8" height="6.1" fill="#919e88"/><rect x="-18.4" y="9" width="5.8" height="3.2" fill="#687860"/><rect x="3.1" y="9.5" width="4.8" height="1.6" fill="#7d8a72"/><rect x="-9.4" y="9.5" width="3.8" height="1.6" fill="#b09e71"/><circle cx="11.5" cy="-9.2" r="3" fill="#b69f6a"/><circle cx="15.9" cy="9.9" r="2.6" fill="#8e9a82"/><circle cx="11.5" cy="11.6" r="1.9" fill="#a1ab94"/><g id="mapMachine"><circle r="2.2" fill="#edbd3b" stroke="#6a6039" stroke-width=".25"/><path d="M1.7 0L-1.05 -1.05L-.55 0L-1.05 1.05Z" fill="#2d3a27"/></g></svg><div id="mapPosition">X +0.0 / Z +0.0 m</div><div id="siteMapLabel">↗ SITE OVERVIEW</div></button>'''
s=s.replace('<div class="compass-note">',widget+'<div class="compass-note">')
s=s.replace('<small id="travelDistance">0.0 m</small></div>', '<small id="travelDistance">0.0 m</small><button id="travelMapButton" aria-pressed="false">↗ SITE OVERVIEW</button></div>')
s=s.replace('<button id="homeDrive" class="reset">↺ &nbsp; RETURN TO START</button>', '<div class="site-travel-footer"><button id="homeDrive" class="reset">↺ &nbsp; RETURN TO START</button><button id="clearTracks">CLEAR TRACK MARKS</button></div>')
s=s.replace('360° MODEL EXPLORER · ASSEMBLY EDITION','INTERACTIVE EARTHWORKS · SITE EDITION')
s=s.replace('<p>Assembly tab:','<p>Site plan: switch between an overview of the yard and following the excavator. Dirt lanes, metre markers and track impressions show travel. Major site obstacles stop the chassis; the boom is not collision-simulated.</p><p>Assembly tab:')
css='''
.compass-note{display:none}.assembly-console .compass-note{display:block}.site-map{position:absolute;right:364px;bottom:126px;width:138px;border:1px solid #a6b39488;border-radius:4px;background:#eceee2e8;color:#54664a;padding:9px;text-align:left;box-shadow:0 3px 15px #34452a08;cursor:pointer;z-index:2}.map-title{display:flex;justify-content:space-between;font:8px monospace;letter-spacing:.7px;margin-bottom:5px}.map-title span{font-size:6px;color:#8b997d;letter-spacing:0}.site-map svg{display:block;width:100%;height:auto}.site-map #mapPosition{font:7px monospace;letter-spacing:.1px;margin-top:5px;color:#8b987d}.site-map #siteMapLabel{font:8px monospace;margin-top:6px;letter-spacing:.5px}.site-map:hover,.site-map[aria-pressed=true]{border-color:#9c8c48}.site-map[aria-pressed=true] #siteMapLabel{color:#947620}.assembly-console .site-map{display:none}.site-overview .heading .tag{color:#8c753b;border-color:#b9ae7f}#travelMapButton{display:block;margin:10px 0 0 auto;border:0;padding:0;background:none;color:#d7be76;font:8px monospace;letter-spacing:.3px;cursor:pointer}#travelMapButton:hover{color:#ffe4a2}.site-travel-footer #clearTracks{border:0;background:none;color:#839777;font:7px monospace;letter-spacing:1px;cursor:pointer;display:block;margin:11px auto 0;padding:0}.site-travel-footer #clearTracks:hover{color:#d3dfbd}
@media(max-width:1050px) and (min-width:761px){.site-map{right:314px;width:125px;bottom:128px}}
@media(max-width:760px){.site-map{right:20px;bottom:174px;width:104px;padding:7px}.map-title{font-size:7px;margin-bottom:4px}.map-title span{font-size:5px}.site-map #mapPosition{font-size:6px;letter-spacing:-.15px}.site-map #siteMapLabel{font-size:7px;letter-spacing:.1px}.controls-open .site-map{display:none}.panel.open #travelMapButton{margin-top:7px;font-size:7px}.panel.open .drive-readout{padding-bottom:8px}.panel.open .site-travel-footer{display:flex;align-items:center;gap:12px}.panel.open .site-travel-footer #homeDrive{flex:1;margin-top:10px;font-size:8px}.panel.open .site-travel-footer #clearTracks{width:76px;flex-shrink:0;margin-top:10px;font-size:6px;line-height:1.8;letter-spacing:.5px}}
'''
s=s.replace('</style>',css+'\n</style>');(p/'page-shell.html').write_text(s)
